// Changes: Tests of the precedence project operations (the G_expr2 example).

import { describe, expect, it } from 'vitest'
import { hasPrecTable, loadPrecExample } from './precOps'
import { analyzePrec, precTable, setRelation, setTerminals, simulatePrec } from './precedence'
import { defaultProjectData, type ProjectData } from './project'

const withPrec = (patch: Partial<ProjectData['prec']>): ProjectData => {
  const d = defaultProjectData()
  return { ...d, prec: { ...d.prec, ...patch } }
}

describe('hasPrecTable – would loading the example overwrite something?', () => {
  it('is false for an empty precedence section', () => {
    expect(hasPrecTable(defaultProjectData())).toBe(false)
    expect(hasPrecTable(withPrec({ rules: ' \n', input: ' ' }))).toBe(false)
  })

  it('is true as soon as terminals, a relation, rules or the input are filled', () => {
    expect(hasPrecTable(withPrec({ terminals: ['i'] }))).toBe(true)
    expect(hasPrecTable(withPrec({ cells: setRelation(defaultProjectData().prec, '$', '$', '=').cells }))).toBe(true)
    expect(hasPrecTable(withPrec({ rules: 'E -> i' }))).toBe(true)
    expect(hasPrecTable(withPrec({ input: 'i' }))).toBe(true)
  })
})

describe('loadPrecExample (G_expr2)', () => {
  it('fills a table that parses i + i * i with * above + (regression: the table used to stay empty)', () => {
    const d = loadPrecExample(defaultProjectData())
    const sim = simulatePrec(d.prec)
    expect(sim?.ok).toBe(true)
    // E → E+E (1), E → E*E (2), E → i (4): i * i is reduced before the +.
    expect(sim?.message).toBe('Úspech. Pravý rozbor: 4 4 4 2 1')
  })

  it('reduces + and * left-associatively', () => {
    const d = loadPrecExample(defaultProjectData())
    expect(simulatePrec({ ...d.prec, input: 'i + i + i' })?.message).toBe('Úspech. Pravý rozbor: 4 4 1 4 1')
    expect(simulatePrec({ ...d.prec, input: 'i * i * i' })?.message).toBe('Úspech. Pravý rozbor: 4 4 2 4 2')
    expect(simulatePrec({ ...d.prec, input: '( i + i ) * i' })?.message).toBe('Úspech. Pravý rozbor: 4 4 1 3 4 2')
  })

  it('rejects an input that is not an expression', () => {
    const d = loadPrecExample(defaultProjectData())
    expect(simulatePrec({ ...d.prec, input: 'i i' })?.ok).toBe(false)
  })

  it('has the terminals i + * ( ) and no problems in the checks', () => {
    const d = loadPrecExample(defaultProjectData())
    expect(precTable(d.prec).columns).toEqual(['i', '+', '*', '(', ')', '$'])
    expect(analyzePrec(d.prec).problems.filter((p) => p.level !== 'info')).toEqual([])
  })

  it('replaces the whole precedence section and leaves the rest of the project alone', () => {
    const before = withPrec(setTerminals(withPrec({ rules: 'X -> y', input: 'y' }).prec, ['y', 'z']))
    before.names.map = 'a=b'
    const d = loadPrecExample(before)
    expect(d.prec.terminals).not.toContain('y')
    expect(d.prec.input).toBe('i + i * i')
    expect(d.names).toEqual(before.names)
    expect(d.ll).toEqual(before.ll)
  })
})
